609	        return jdbc.query("SELECT * FROM fumigation_approval WHERE request_id = ?",
610	                (rs, rowNum) -> new ApprovalRow(rs.getLong("id"), rs.getLong("fumigation_id"),
611	                        rs.getString("approver"), rs.getString("fingerprint")),
612	                requestId).stream().findFirst();
613	    }
614	
615	    private Optional<ReadingRow> findGasReadingByRequestId(String requestId) {
616	        return jdbc.query("SELECT * FROM gas_reading WHERE request_id = ?",
617	                FumigationService::mapGasReading, requestId).stream().findFirst();
618	    }
619	
