666	        return new ReadingRow(rs.getLong("id"), rs.getLong("fumigation_id"), rs.getInt("seq_no"),
667	                rs.getBigDecimal("concentration"), toInstant(rs, "measured_at"),
668	                rs.getBoolean("late"), rs.getString("fingerprint"), rs.getString("request_id"));
669	    }
