12	 * 同键同参可重放首次结果，同键异参判冲突。
13	 */
14	public final class Fingerprints {
15	
16	    private Fingerprints() {
17	    }
18	
19	    /**
20	     * 计算指纹；字段按声明顺序以竖线拼接，null 以固定占位符参与。
21	     *
22	     * @param parts requestId 及全部业务字段
23	     * @return 64 位十六进制摘要
