30	    }
31	
32	    /**
33	     * 结构化指纹：每个字段以“类型:UTF-8字节长度:值”编码，字段首尾定界，
34	     * 即使合法文本本身含有分隔符（如冒号、竖线）也无法伪造字段边界，无歧义。
35	     *
36	     * @param parts requestId 及全部业务字段（标量），集合请先用 {@link #stringList} 编码
37	     * @return 64 位十六进制摘要
38	     */
39	    public static String structured(Object... parts) {
40	        StringBuilder raw = new StringBuilder();
41	        for (Object part : parts) {
42	            if (part == null) {
43	                raw.append("N:0:");
44	            } else {
45	                byte[] bytes = part.toString().getBytes(StandardCharsets.UTF_8);
46	                raw.append("S:").append(bytes.length).append(':').append(part);
47	            }
48	        }
49	        return sha256(raw.toString());
50	    }
51	
52	    /**
53	     * 将字符串集合编码为单个结构化字段：先给元素个数，再逐元素长度定界；
54	     * null 集合与空集合编码不同，元素顺序参与指纹。
55	     */
56	    public static String stringList(List<String> values) {
57	        if (values == null) {
58	            return "N:0:";
59	        }
60	        StringBuilder raw = new StringBuilder("L:").append(values.size()).append(':');
61	        for (String value : values) {
62	            byte[] bytes = (value == null ? "" : value).getBytes(StandardCharsets.UTF_8);
63	            raw.append(bytes.length).append(':').append(value == null ? "" : value);
64	        }
65	        return raw.toString();
66	    }
67	
68	    private static String sha256(String raw) {
69	        try {
70	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
71	            byte[] hash = digest.digest(raw.getBytes(StandardCharsets.UTF_8));
72	            StringBuilder hex = new StringBuilder(hash.length * 2);
73	            for (byte b : hash) {
74	                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
75	                hex.append(Character.forDigit(b & 0xF, 16));
76	            }
77	            return hex.toString();
78	        } catch (NoSuchAlgorithmException e) {
79	            throw new IllegalStateException("SHA-256 不可用", e);
80	        }
81	    }
