41	    @Test
42	    void highReadingCompetingWithReleaseMustNotReleaseOnStaleVersion() throws Exception {
43	        var silo = newSilo("S-FC-1");
44	        var fan = newFan("F-FC-1");
45	        long orderId = aeratingOrder(silo.id(), fan.id(), "fc-1");
46	        // 已有点 1,2,3 安全，当前版本 8，三点首末恰 30 分钟可解除
47	        safeThreeReadings(orderId, 5, "fc-1");
48	        assertEquals(8, fumigationService.getOrder(orderId).version());
49	
50	        ExecutorService pool = Executors.newFixedThreadPool(2);
51	        CountDownLatch gate = new CountDownLatch(1);
52	        try {
53	            // 线程 A 用旧版本 8 解除；线程 B 补录序号 4 的高浓度读数（同样带版本 8）
54	            Future<Result<ReleaseView>> releaseFuture = pool.submit(() -> {
55	                gate.await();
56	                return call(() -> fumigationService.release(orderId,
57	                        new ReleaseFumigationRequest("fc-1-rel", 8, List.of("carol", "dave"))));
58	            });
59	            Future<Result<GasReadingView>> readingFuture = pool.submit(() -> {
60	                gate.await();
61	                return call(() -> fumigationService.ingestGasReading(orderId,
62	                        new GasReadingRequest("fc-1-g4-high", 8, 4, new BigDecimal("50.000"),
63	                                U0.plusSeconds(9000))));
64	            });
65	            gate.countDown();
66	            Result<ReleaseView> releaseOutcome = releaseFuture.get(15, TimeUnit.SECONDS);
67	            Result<GasReadingView> readingOutcome = readingFuture.get(15, TimeUnit.SECONDS);
68	
69	            boolean readingOk = readingOutcome.error() == null;
70	            boolean releaseOk = releaseOutcome.error() == null;
71	            // 真正禁止的是：高浓度读数作为正常证据（非迟到）入库的同时解除成功——那等于用旧三点放行
72	            assertFalse(readingOk && !readingOutcome.value().late() && releaseOk,
73	                    "高浓度正常补录与解除不得同时成功");
